import{_ as r,o as a,c as t,a5 as o}from"./chunks/framework.CslsFoWx.js";const i="/VendoraSystem-docs/captures/2026-11-08-corrections-appairage/02-refus-session-ouverte.webp",s="/VendoraSystem-docs/captures/2026-11-08-corrections-appairage/03-confirmation.webp",p="/VendoraSystem-docs/captures/2026-11-08-corrections-appairage/04-pin-manager.webp",d="/VendoraSystem-docs/captures/2026-11-08-corrections-appairage/05-serveur-injoignable.webp",c="/VendoraSystem-docs/captures/2026-11-08-corrections-appairage/06-ecran-appairage-vierge.webp",n="/VendoraSystem-docs/captures/2026-11-08-corrections-appairage/07-limite-formule.webp",l="/VendoraSystem-docs/captures/2026-11-08-corrections-appairage/08-titre-resto-part-egale-avant.webp",u="/VendoraSystem-docs/captures/2026-11-08-corrections-appairage/09-titre-resto-part-egale-apres.webp",S=JSON.parse('{"title":"Corrections appairage / désappairage et apps (lot HM, partie 2) — 08/11/2026","description":"","frontmatter":{},"headers":[],"relativePath":"preuves/2026-11-08-corrections-appairage.md","filePath":"generated/preuves/2026-11-08-corrections-appairage.md","lastUpdated":null}'),m={name:"preuves/2026-11-08-corrections-appairage.md"};function g(v,e,f,h,b,P){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="corrections-appairage-desappairage-et-apps-lot-hm-partie-2-—-08-11-2026" tabindex="-1">Corrections appairage / désappairage et apps (lot HM, partie 2) — 08/11/2026 <a class="header-anchor" href="#corrections-appairage-desappairage-et-apps-lot-hm-partie-2-—-08-11-2026" aria-label="Permalink to &quot;Corrections appairage / désappairage et apps (lot HM, partie 2) — 08/11/2026&quot;">​</a></h1><p class="muted">Dossier <code>docs/captures/2026-11-08-corrections-appairage</code> · 0 image(s) · 0 trace(s)</p><div><p>Défauts relevés par le centre d&#39;aide (<code>docs/DEFAUTS-CENTRE-AIDE.md</code>, « Lot HM ») : désappairage guidé (confirmation + PIN manager), révocation au serveur (place libérée dans la formule), session jamais reprise d&#39;un appairage à l&#39;autre, « Première synchronisation… », écran d&#39;appairage vierge, champs Android synchrones, pavé PIN en tablette paysage, mode formation vérifié avant le PIN, limite de formule / compte suspendu lisibles, texte caméra QR + codes-barres.</p><h2 id="captures-faites-le-08-11-2026-vraie-stack-ios" tabindex="-1">Captures (faites le 08/11/2026, vraie stack iOS) <a class="header-anchor" href="#captures-faites-le-08-11-2026-vraie-stack-ios" aria-label="Permalink to &quot;Captures (faites le 08/11/2026, vraie stack iOS)&quot;">​</a></h2><p>Commerce de démo fictif <code>bistrot.demo+tr1108@vendora.test</code> (« Le Petit Bistrot (démo) », EUR) ; simulateurs dédiés « Agent-a3d7-iPad » (iPad Air 11&quot; M3, caisse principale) et « Agent-a3d7-iPhone » (iPhone 16, téléphone de salle), supprimés ensuite ; gestes par le pilote XCUITest du dépôt (<code>help/tools/mobile/pilote-ios</code>, sans outil MCP). Scénarios d&#39;annotation : <code>help/tools/mobile/scenarios/appareil-caisse-desappairer-ios.json</code> (iPad) et <code>appareil-caisse-desappairer-iphone-ios.json</code> (iPhone) ; mêmes images dans <code>help/public/captures/appareil-caisse/desappairer/</code>.</p><table tabindex="0"><thead><tr><th>Capture</th><th>Appareil</th><th>Ce qu&#39;elle montre</th></tr></thead><tbody><tr><td><img src="'+i+'" alt=""> <code>02-refus-session-ouverte</code></td><td>iPad</td><td>Refus motivé : « Session de caisse n° 1 ouverte : clôturez-la (rapport Z) avant de désappairer… », aucun PIN demandé.</td></tr><tr><td><img src="'+s+'" alt=""> <code>03-confirmation</code></td><td>iPhone</td><td>« Désappairer cet appareil ? » — ce qui va se passer, <strong>Annuler</strong> / <strong>Continuer</strong>.</td></tr><tr><td><img src="'+p+'" alt=""> <code>04-pin-manager</code></td><td>iPhone</td><td>PIN manager, motif pré-rempli « Désappairage de l&#39;appareil ».</td></tr><tr><td><img src="'+d+'" alt=""> <code>05-serveur-injoignable</code></td><td>iPhone</td><td>Serveur arrêté : <strong>Réessayer</strong> / <strong>Désappairer quand même</strong> / Annuler. Serveur relancé puis <strong>Réessayer</strong> → désappairé, appareil <code>REVOKED</code> au serveur (« Désappairé depuis l&#39;appareil : Désappairage de l&#39;appareil »).</td></tr><tr><td><img src="'+c+'" alt=""> <code>06-ecran-appairage-vierge</code></td><td>iPhone</td><td>Retour sur « Appairer cet appareil », champs vierges (seule l&#39;URL du serveur est gardée).</td></tr><tr><td><img src="'+n+'" alt=""> <code>07-limite-formule</code></td><td>iPhone</td><td>Code créé sous la limite puis consommé formule pleine (appareils factices) : « Limite de la formule Restaurant atteinte : 6 appareils de vente… » au lieu de « Erreur serveur (HTTP_409) ».</td></tr><tr><td><img src="'+l+'" alt=""> <code>08-titre-resto-part-egale-avant</code></td><td>iPhone</td><td>Défaut titre-restaurant reproduit : part égale « Part 1/4 » d&#39;une addition entrecôte + terrine (éligibles) → « Aucun article éligible ».</td></tr><tr><td><img src="'+u+'" alt=""> <code>09-titre-resto-part-egale-apres</code></td><td>iPhone</td><td>Après correction : « Éligible : 7,50 € · plafond : 25,00 € · autorisé : 7,50 € », part encaissée en titre-restaurant.</td></tr></tbody></table><p><strong>Défaut trouvé en faisant ces captures (corrigé, iOS)</strong> : sur iPhone, <strong>Continuer</strong> ne faisait rien — la fermeture de l&#39;alerte de confirmation remettait <code>isPresented</code> à faux, ce qui appelait <code>annuler()</code> juste après <code>confirmer()</code> : l&#39;étape PIN et sa feuille étaient effacées (<code>DesappairageModifier</code>, test <code>testContinuerOuvreLaFeuillePinMalgreLaFermetureDeLAlerte</code>). Android n&#39;est pas concerné (<code>onDismissRequest</code> n&#39;est pas appelé par les boutons d&#39;un <code>AlertDialog</code> Compose).</p><p><strong>Non faites</strong> :</p><ul><li>« Première synchronisation… » : sur un petit catalogue, l&#39;écran « Qui êtes-vous ? » se remplit en moins d&#39;une seconde ; trois captures enchaînées juste après <strong>Appairer</strong> ne l&#39;ont pas attrapé.</li><li>Android (tablette) : machine trop chargée pour un troisième émulateur (deux émulateurs de l&#39;utilisateur + deux simulateurs, 16 Go) — à faire avec <code>help/tools/mobile/appareils.sh creer-android tablette</code>.</li><li>Le serveur de dev du port 8080 (démarré le 07/11, avant <code>POST /api/v1/pos/device/unpair</code>) répondait 404 au désappairage, affiché « Serveur injoignable » : les captures de désappairage complet ont été faites contre un serveur du worktree (port 8088). Redémarrer le serveur de dev pour avoir le comportement à jour.</li></ul><p>Le comportement est couvert par les tests automatiques : <code>DeviceSelfUnpairIntegrationTest</code> (serveur), <code>DeviceUnpairingTest</code> (shared), <code>UnpairViewModelTest</code> et <code>PairingViewModelTest</code> (Android), <code>DesappairageTests</code> (iOS).</p><h2 id="scenario-pour-rejouer-les-captures" tabindex="-1">Scénario pour rejouer les captures <a class="header-anchor" href="#scenario-pour-rejouer-les-captures" aria-label="Permalink to &quot;Scénario pour rejouer les captures&quot;">​</a></h2><ol><li>Serveur du worktree sur un port libre (<code>./gradlew :server:bootRun --args=&#39;--server.port=8086&#39;</code>) contre la base de dev ; commerce de démo fictif : <code>python3 -I help/tools/seed/seed-demo.py --owner-email bistrot.demo+hm@vendora.test --secrets &amp;lt;hors dépôt&gt; --api http://localhost:8086 --no-activity</code> (« Le Petit Bistrot (démo) »).</li><li>Appareils dédiés : <code>help/tools/mobile/appareils.sh creer-ios</code> / <code>creer-android tablette</code> (1600 × 1000, utile aussi pour vérifier le pavé PIN côte à côte).</li><li>Code d&#39;appairage <code>REGISTER</code> (back-office ou <code>POST /api/v1/devices/pairing-codes</code>), appairer avec l&#39;URL du serveur.</li><li>Après la première synchronisation : « Qui êtes-vous ? » → <strong>Désappairer cet appareil</strong> → capture <code>01-confirmation</code> ; <strong>Continuer</strong> → capture <code>02-pin-manager</code> ; PIN de « Sophie (manager) » → écran d&#39;appairage vierge (<code>03-ecran-appairage-vierge</code>), appareil révoqué au back-office (<code>04-fiche-revoquee</code>).</li><li>Limite de formule : abonnement Essentiel (1 appareil) pour le commerce de démo, deux codes créés sous la limite puis le second consommé sur l&#39;appareil → « Limite de la formule Essentiel atteinte : 1 appareil de vente… » (<code>05-limite-formule</code>), au lieu de « Erreur serveur (HTTP_409) — réessayez ».</li><li>Session ouverte : ouvrir une session puis <strong>Désappairer</strong> → refus « Session de caisse n° 1 ouverte : clôturez-la (rapport Z)… » (<code>06-refus-session-ouverte</code>).</li></ol><p>Note : un commerce de démo « Le Petit Bistrot (démo) » (<code>bistrot.demo+hmcorr@vendora.test</code>) a été semé dans la base de dev pendant la préparation ; il est fictif et peut être réutilisé pour ces captures.</p></div>',3)])])}const A=r(m,[["render",g]]);export{S as __pageData,A as default};
